import { Cliente, Producto, Factura, AbonoCredito, ConfigEmpresa, ResumenVentas } from './types';

export const LOGO_BASE64 = `data:image/png;base64,`;

export function formatearDinero(valor: number = 0): string {
  return Number(valor || 0).toLocaleString('es-DO', {
    style: 'currency',
    currency: 'DOP',
    minimumFractionDigits: 2,
  });
}

export function formatearFechaHora(fechaIso?: string): { fecha: string; hora: string } {
  if (!fechaIso) return { fecha: '', hora: '' };
  const d = new Date(fechaIso);
  if (isNaN(d.getTime())) return { fecha: '', hora: '' };
  return {
    fecha: d.toLocaleDateString('es-DO', { year: 'numeric', month: '2-digit', day: '2-digit' }),
    hora: d.toLocaleTimeString('es-DO', { hour: '2-digit', minute: '2-digit', hour12: true }),
  };
}

export function fechaHoyYMD(): string {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

export function calcularResumen(facturas: Factura[], productos: Producto[], abonos: AbonoCredito[] = []): ResumenVentas {
  const ahora = new Date();
  const hoyStr = fechaHoyYMD();

  // Inicio de semana (Lunes)
  const dSemana = new Date(ahora);
  const dia = dSemana.getDay();
  const dif = dia === 0 ? 6 : dia - 1;
  dSemana.setDate(dSemana.getDate() - dif);
  dSemana.setHours(0, 0, 0, 0);

  // Inicio de quincena (1 o 16 del mes)
  const dQuincena = new Date(ahora.getFullYear(), ahora.getMonth(), ahora.getDate() <= 15 ? 1 : 16);
  dQuincena.setHours(0, 0, 0, 0);

  // Inicio de mes
  const dMes = new Date(ahora.getFullYear(), ahora.getMonth(), 1);
  dMes.setHours(0, 0, 0, 0);

  let hoy = 0;
  let semana = 0;
  let quincena = 0;
  let mes = 0;
  let contadoHoy = 0;
  let creditoHoy = 0;
  let cantidadFacturasHoy = 0;
  let deudaTotalPendiente = 0;

  facturas.forEach((f) => {
    if (f.estado === 'anulada') return;
    const fFecha = new Date(f.fecha);
    const total = Number(f.total || 0);
    const esHoy = String(f.fecha).substring(0, 10) === hoyStr;

    if (esHoy) {
      hoy += total;
      cantidadFacturasHoy++;
      if (f.formaPago === 'contado') contadoHoy += total;
      else creditoHoy += total;
    }

    if (fFecha >= dSemana) semana += total;
    if (fFecha >= dQuincena) quincena += total;
    if (fFecha >= dMes) mes += total;

    // Saldo pendiente
    if (f.formaPago === 'credito') {
      const saldo = f.saldoCredito !== undefined ? Number(f.saldoCredito) : total;
      if (saldo > 0) deudaTotalPendiente += saldo;
    }
  });

  // Cobros / abonos recibidos hoy
  let cobrosHoy = 0;
  abonos.forEach((ab) => {
    if (String(ab.fecha).substring(0, 10) === hoyStr) {
      cobrosHoy += Number(ab.monto || 0);
    }
  });

  // Productos con bajo stock
  const productosBajoStock = productos.filter((p) => Number(p.stock || 0) <= Number(p.stockMinimo ?? 5)).length;

  return {
    hoy,
    semana,
    quincena,
    mes,
    contadoHoy,
    creditoHoy,
    cobrosHoy,
    cantidadFacturasHoy,
    deudaTotalPendiente,
    productosBajoStock,
  };
}

export function generarNumeroFactura(facturas: Factura[]): string {
  if (!facturas || facturas.length === 0) return 'FAC-0001';
  let mayor = 0;
  facturas.forEach((f) => {
    const n = String(f.numero || '').replace(/\D/g, '');
    const num = Number(n || 0);
    if (num > mayor) mayor = num;
  });
  return 'FAC-' + String(mayor + 1).padStart(4, '0');
}

export function escapeHtml(text?: string | number): string {
  return String(text ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}
